//! Lua binding registrars, ported table-driven.
//!
//! Each registrar builds a `{name, fn}` array on its stack and loops over it with
//! `lua_pushstring(name)`, `lua_pushcclosure(fn, 0)`, `luaV_settable(L, L+0x40, top-2, top-1)` and
//! `top -= 2`. Here the arrays are tables (extracted from the original bytes by
//! scratchpad/registrars/gen.py, which also accounts for every instruction of every body) and
//! the loop calls the same three helpers by address, in the same order.
//!
//! Variations kept in place: the null-L early-out (`test esi, esi`) where the original has one,
//! the registrars called before it (pause_menu_lua_register) or around the entries
//! (interface_register_lua_functions at 0x7f35a0), the trailing registrar calls of
//! script_register_game_functions, and the global that holds L for the game (0x252983c) and
//! vint (0x252a1b8) registrars.

use crate::portlib::*;
use crate::log;
use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};

const PUSHSTRING: usize = 0xcdcaf0;
const PUSHCCLOSURE: usize = 0xcdcd30;
const SETTABLE: usize = 0xcd68d0;

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    /// Name in EAX, function in ECX, top-2 in EAX and top-1 in EDX at the settable call.
    Std,
    /// The vint registrar keeps the name in ECX, the function in EDX, top-1 in ECX, L+0x40 in EDX.
    Vint,
}

struct Reg {
    name: &'static str,
    addr: usize,
    body: &'static [u8],
    entries: &'static [(u32, u32)],
    null_check: bool,
    /// Address of the global holding L, or 0 when L arrives in EAX (or on the stack).
    l_global: usize,
    /// Registrars called with EAX = L before the entries.
    pre: &'static [usize],
    /// Registrars called with EAX = L after the entries.
    post: &'static [usize],
    kind: Kind,
    calls: AtomicU32,
    registered: AtomicU32,
    first: AtomicBool,
}

/// Register one `{name, fn}` entry the way the loop body does.
unsafe fn register_one(kind: Kind, l: u32, name: u32, f: u32) {
    unsafe {
        match kind {
            Kind::Std => call_regs(PUSHSTRING, name, 0, 0, l, 0, &[name]),
            Kind::Vint => call_regs(PUSHSTRING, 0, name, 0, l, 0, &[name]),
        };
        match kind {
            Kind::Std => call_regs(PUSHCCLOSURE, 0, f, 0, l, 0, &[f, 0]),
            Kind::Vint => call_regs(PUSHCCLOSURE, 0, 0, f, l, 0, &[f, 0]),
        };
        let top = rd(l as usize + 8);
        let (t2, t1) = (top.wrapping_sub(0x20), top.wrapping_sub(0x10));
        match kind {
            Kind::Std => call_regs(SETTABLE, t2, 0, t1, l, 0, &[l, l + 0x40, t2, t1]),
            Kind::Vint => call_regs(SETTABLE, t2, t1, l + 0x40, l, 0, &[l, l + 0x40, t2, t1]),
        };
        wd(l as usize + 8, rd(l as usize + 8).wrapping_sub(0x20));
    }
}

extern "C" fn run(idx: u32, l_arg: u32) {
    let r = &REGS[idx as usize];
    unsafe {
        let l = if r.l_global != 0 { rd(r.l_global) } else { l_arg };
        let top0 = if l != 0 { rd(l as usize + 8) } else { 0 };
        let before = r.registered.load(Ordering::Relaxed);
        for &p in r.pre {
            call_regs(p, l, 0, 0, l, 0, &[]);
        }
        if !(r.null_check && l == 0) {
            for &(name, f) in r.entries {
                register_one(r.kind, l, name, f);
                r.registered.fetch_add(1, Ordering::Relaxed);
            }
        }
        for &p in r.post {
            call_regs(p, l, 0, 0, l, 0, &[]);
        }
        r.calls.fetch_add(1, Ordering::Relaxed);
        if !r.first.swap(true, Ordering::Relaxed) {
            let got = r.registered.load(Ordering::Relaxed) - before;
            let top1 = if l != 0 { rd(l as usize + 8) } else { 0 };
            log(&format!(
                "port_registrars: {} first call: {} entries registered (expected {}), L={:#x}, top moved {:#x}",
                r.name, got, r.entries.len(), l, top1.wrapping_sub(top0)
            ));
        }
    }
}

/// Thunk for the registrars that take L in EAX.
macro_rules! thunk_eax {
    ($name:ident, $idx:expr) => {
        #[unsafe(naked)]
        extern "C" fn $name() {
            std::arch::naked_asm!("push eax", "push {i}", "call {f}", "add esp, 8", "ret", i = const $idx, f = sym run)
        }
    };
}

/// Thunk for the registrar that takes L as a cdecl stack argument.
macro_rules! thunk_stack {
    ($name:ident, $idx:expr) => {
        #[unsafe(naked)]
        extern "C" fn $name() {
            std::arch::naked_asm!("push dword ptr [esp + 4]", "push {i}", "call {f}", "add esp, 8", "ret", i = const $idx, f = sym run)
        }
    };
}

// --- install ------------------------------------------------------------------------------------

/// Install this module's replacements (called from hooks::install_all).
pub fn install() {
    let mut ok = 0;
    let mut expected = 0;
    for (i, r) in REGS.iter().enumerate() {
        expected += r.entries.len();
        if replace_pinned(r.name, r.addr, r.body, THUNKS[i] as usize) {
            ok += 1;
        }
    }
    log(&format!("port_registrars: replaced {ok}/{} with Rust ({expected} entries in the tables)", REGS.len()));
}

/// One line for the periodic log.
pub fn summary() -> String {
    let parts: Vec<String> = REGS
        .iter()
        .filter_map(|r| {
            let c = r.calls.load(Ordering::Relaxed);
            (c > 0).then(|| {
                format!(
                    "{} {c} ({} / {})",
                    r.name,
                    r.registered.load(Ordering::Relaxed),
                    c as usize * r.entries.len()
                )
            })
        })
        .collect();
    if parts.is_empty() { String::new() } else { format!("port_registrars: {}", parts.join(", ")) }
}

